head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > displayAllOptionLabel]<br/>allOption=true 일때 아이템이 모두 선택되면 컴포넌트의 라벨 표시 영역에 '전체 선택' 을 표시할지 설정합니다.",
    "validation" : [
        "checkDisabledOnAllCheck=false 이고 비활성화된 아이템이 있는 경우 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    let properties = {
        allOption : true,
        checkDisabledOnAllCheck : false,
        enableColumn : "enable_col",
        displayAllOptionLabel : true,
    }

    $c.gcm.createLabel('label="전체선택 후 Component 정보 확인 시 label : 4 5 6 7 8 이면 정상"', '', 'label1');

    let cList = $c.gcm.createCList(properties)    

    strTarget += '<xf:checkcombobox ' + strNameSpace + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_statusItem">';
    strTarget += '<xf:label ref="label_col"></xf:label>';
    strTarget += '<xf:value ref="value_col"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:checkcombobox>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "checkcombobox",
        strTarget,
        grp_comp
    );
}




scwin.btn_getCompInfo_onclick = function (e) {   
    let rtn = ''

    rtn = target1.render.textContent;
    wf_body_bottom.getObj("scwin").setReturnValue("label : " + rtn);  

    rtn = target1.getText();
    wf_body_bottom.getObj("scwin").setReturnValue("getText : " + rtn);  

    rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);  
}
